-- Replace the generic PHB shop placeholders with useful, original summaries.
-- The Go-side phase of this migration then normalizes every public type-2
-- description into rich HTML and adds semantic dice/stat/reference nodes.
CREATE TEMP TABLE item_description_seed ON COMMIT DROP AS
SELECT * FROM (VALUES
    ('Abacus', 'Рамка с нанизанными на спицы костяшками для быстрых расчётов. Счёты удобны торговцам, казначеям и всем, кому приходится вести учёт без бумаги.'),
    ('Acid (vial)', 'Флакон едкой кислоты. Действием кислоту можно выплеснуть на существо в пределах 5 футов или метнуть как импровизированное оружие на расстояние до 20 футов; при попадании цель получает 2d6 урона кислотой.'),
    ('Alchemist''s fire (flask)', 'Липкая горючая смесь воспламеняется при контакте с воздухом. Действием флягу можно метнуть как импровизированное оружие на расстояние до 20 футов. При попадании цель получает 1d4 урона огнём в начале каждого своего хода, пока не потратит действие и не пройдёт проверку Ловкости Сл 10, чтобы погасить пламя.'),
    ('Amulet', 'Священный символ в виде подвески на цепочке. Жрец или паладин может использовать его как фокусировку для заклинаний, если носит амулет на виду или держит в руке.'),
    ('Antitoxin (vial)', 'Существо может действием выпить флакон противоядия и на 1 час получить преимущество на спасброски от яда. Противоядие не действует на нежить и конструктов.'),
    ('Arrow', 'Древко с оперением и металлическим наконечником — боеприпас для коротких и длинных луков. После боя можно потратить минуту и вернуть половину выпущенных стрел, если поле боя доступно для поиска.'),
    ('Backpack', 'Заплечная сумка с ремнями, рассчитанная примерно на 30 фунтов снаряжения или 1 кубический фут содержимого. Снаружи обычно можно закрепить дополнительные предметы, например спальник или верёвку.'),
    ('Ball bearings (bag of 1,000)', 'Мешочек мелких металлических шариков покрывает ровную площадку 10 × 10 футов. Существо, проходящее по ней не вполовину скорости, должно пройти спасбросок Ловкости Сл 10, иначе падает ничком. Сбор рассыпанных шариков занимает около 10 минут.'),
    ('Barrel', 'Прочная деревянная бочка с обручами. В неё помещается до 40 галлонов жидкости или около 4 кубических футов сухого груза.'),
    ('Basket', 'Плетёная корзина для переноски припасов и мелкого груза. Она вмещает примерно 40 фунтов или 2 кубических фута содержимого.'),
    ('Bedroll', 'Сворачиваемая подстилка с тёплым верхним слоем для ночёвки в дороге. Она изолирует от холодной и сырой земли, но не заменяет укрытие от непогоды.'),
    ('Bell', 'Небольшой ручной колокольчик с ясным звоном. Его используют как сигнал, подвешивают к двери или включают в простую сигнальную ловушку.'),
    ('Blanket', 'Плотное шерстяное одеяло для сна, согревания пострадавшего или защиты груза. В свёрнутом виде его удобно крепить к рюкзаку.'),
    ('Block and tackle', 'Система блоков с пропущенным через них тросом и крюком. Закрепив её над грузом, персонаж может поднимать вес, в четыре раза превышающий тот, который обычно способен поднять.'),
    ('Blowgun needle', 'Тонкая игла — боеприпас для духовой трубки. После боя можно потратить минуту и вернуть половину выпущенных игл, если их возможно отыскать.'),
    ('Book', 'Защитный переплёт и плотные страницы сохраняют записи в дороге. Книга может содержать хронику, религиозный текст, научный трактат или чистые листы по выбору владельца.'),
    ('Bottle, glass', 'Стеклянная бутылка с узким горлышком и пробкой. Она вмещает около полутора пинт жидкости.'),
    ('Burglar''s Pack', 'Набор для скрытого проникновения: инструменты для простых сигнализаций и преодоления преград, фонарь, масло, припасы и верёвка. Полный состав показан ниже.'),
    ('Bucket', 'Деревянное или металлическое ведро с ручкой. В него входит до 3 галлонов жидкости либо примерно половина кубического фута сыпучего груза.'),
    ('Caltrops', 'Мешочек железных шипов покрывает площадку 5 × 5 футов. Существо, проходящее по ней не вполовину скорости, должно пройти спасбросок Ловкости Сл 15; при провале оно получает 1 колющего урона, останавливается и теряет 10 футов скорости, пока не восстановит хотя бы 1 хит.'),
    ('Candle', 'Свеча горит 1 час, создавая яркий свет в радиусе 5 футов и тусклый свет ещё на 5 футов. Её легко задуть или закрыть от ветра фонарём.'),
    ('Case, crossbow bolt', 'Жёсткий футляр защищает арбалетные болты от влаги и повреждений. В него помещается до двадцати болтов.'),
    ('Case, map or scroll', 'Цилиндрический кожаный футляр не даёт картам и свиткам смяться или промокнуть. Внутри помещается до десяти свёрнутых листов бумаги либо пяти листов пергамента.'),
    ('Chain (10 feet)', 'Десятифутовая железная цепь выдерживает грубое обращение и подходит для крепления тяжёлого груза. У цепи 10 хитов; разорвать её можно успешной проверкой Силы Сл 20.'),
    ('Chalk (1 piece)', 'Кусок белого или цветного мела оставляет хорошо заметные, но легко стираемые отметки на камне, дереве и других шероховатых поверхностях.'),
    ('Chest', 'Окованный деревом сундук для хранения ценностей и снаряжения. Он вмещает примерно 300 фунтов или 12 кубических футов содержимого и может быть заперт навесным замком.'),
    ('Clothes, common', 'Простой и прочный повседневный комплект одежды без заметных украшений. Он подходит ремесленнику, крестьянину или путешественнику с небогатым видом.'),
    ('Clothes, costume', 'Сценический костюм, подобранный для определённой роли или представления. Он меняет общий образ, но сам по себе не является полноценным набором для грима.'),
    ('Clothes, fine', 'Комплект дорогой одежды из качественной ткани с аккуратной отделкой. Такой наряд уместен при дворе, на приёме или в богатом торговом квартале.'),
    ('Clothes, traveler''s', 'Прочная дорожная одежда с плащом, сапогами и несколькими слоями на случай перемены погоды. Она рассчитана на долгие переходы и частый ремонт.'),
    ('Component pouch', 'Небольшая поясная сумка с отделениями для материальных компонентов заклинаний. Она заменяет компоненты без указанной стоимости, но не содержит дорогие или расходуемые материалы.'),
    ('Crystal', 'Обработанный кристалл, настроенный на проведение тайной магии. Волшебник, колдун или чародей может использовать его как магическую фокусировку вместо компонентов без указанной стоимости.'),
    ('Crossbow bolt', 'Короткий тяжёлый боеприпас для арбалета. После боя можно потратить минуту и вернуть половину выпущенных болтов, если их возможно отыскать.'),
    ('Crowbar', 'Тяжёлый железный лом для поддевания крышек, дверей и камней. При подходящей точке опоры он даёт преимущество на проверки Силы, где можно применить рычаг.'),
    ('Dungeoneer''s Pack', 'Готовый набор для исследования подземелий: освещение, припасы, инструменты для взлома преград и страховочная верёвка. Полный состав показан ниже и выдаётся одной покупкой.'),
    ('Diplomat''s Pack', 'Дорожный набор для переговоров и официальных визитов: хорошая одежда, письменные принадлежности, светильник, благовония и сундук. Полный состав показан ниже.'),
    ('Entertainer''s Pack', 'Снаряжение для гастролирующего артиста: дорожные припасы, костюмы, свечи и принадлежности для грима. Полный состав показан ниже.'),
    ('Emblem', 'Священный символ, нанесённый или закреплённый на щите. Жрец или паладин может использовать эмблему как фокусировку для заклинаний, если держит щит обычным образом.'),
    ('Explorer''s Pack', 'Универсальный походный набор с постелью, огнём, пищей, водой и верёвкой. Он рассчитан на несколько дней пути; полный состав показан ниже.'),
    ('Flask or tankard', 'Прочная фляга или кружка вмещает одну пинту жидкости. Флягу можно закрыть пробкой, а кружка удобнее для питья на привале.'),
    ('Grappling hook', 'Многозубый железный крюк, который привязывают к верёвке и забрасывают на уступ, балку или стену. Надёжность зацепа зависит от поверхности и проверки, назначенной Мастером.'),
    ('Hammer', 'Обычный рабочий молоток для забивания гвоздей, шлямбуров и мелкого ремонта снаряжения.'),
    ('Hammer, sledge', 'Тяжёлая двуручная кувалда для разрушения кладки, забивания крупных кольев и другой силовой работы.'),
    ('Healer''s Kit', 'Кожаный футляр с бинтами, мазями и шинами содержит 10 применений. Действием можно потратить одно применение, чтобы стабилизировать существо с 0 хитов без проверки Мудрости (Медицина).'),
    ('Holy water (flask)', 'Освящённая вода обжигает исчадий и нежить. Действием флягу можно выплеснуть на цель в пределах 5 футов или метнуть как импровизированное оружие на расстояние до 20 футов; при попадании исчадие или нежить получает 2d6 урона излучением.'),
    ('Hourglass', 'Стеклянный сосуд с отмеренным количеством песка показывает фиксированный промежуток времени. Его нужно поставить ровно и перевернуть для нового отсчёта.'),
    ('Hunting trap', 'Стальной капкан крепится цепью к неподвижному объекту. Существо, наступившее на нажимную пластину, должно пройти спасбросок Ловкости Сл 13, иначе получает 1d4 колющего урона и теряет возможность двигаться дальше цепи; освободиться можно проверкой Силы Сл 13.'),
    ('Ink (1 ounce bottle)', 'Унция стойких чернил во флаконе — запас для писца, картографа или мага. Одного флакона хватает на множество страниц обычного текста.'),
    ('Ink pen', 'Заострённое перо или металлический наконечник для письма чернилами. Качество пера влияет на аккуратность мелких букв и линий.'),
    ('Jug or pitcher', 'Керамический или металлический кувшин с ручкой. Он вмещает до одного галлона жидкости.'),
    ('Ladder (10-foot)', 'Прямая десятифутовая лестница позволяет преодолеть невысокую стену, яму или уступ, если её есть куда надёжно поставить.'),
    ('Lamp', 'Масляная лампа горит 6 часов на одной пинте масла. Она создаёт яркий свет в радиусе 15 футов и тусклый свет ещё на 30 футов.'),
    ('Lantern, bullseye', 'Направленный фонарь горит 6 часов на одной пинте масла. Он создаёт конус яркого света длиной 60 футов и тусклого света ещё на 60 футов.'),
    ('Lantern, hooded', 'Закрытый фонарь горит 6 часов на одной пинте масла, создавая яркий свет в радиусе 30 футов и тусклый ещё на 30 футов. Опущенная заслонка оставляет только тусклый свет в радиусе 5 футов.'),
    ('Little bag of sand', 'Мешочек мелкого сухого песка используют для просушки свежих чернил, проверки движения воздуха или как малозаметный груз.'),
    ('Lock', 'Обычный навесной замок поставляется с ключом. Без ключа его можно открыть воровскими инструментами при успешной проверке Ловкости Сл 15; Мастер может назначить другую сложность для необычного замка.'),
    ('Magnifying glass', 'Линза помогает рассматривать мелкие детали и даёт преимущество на проверки характеристик при оценке небольшого или очень детального предмета. В солнечный день ею также можно разжечь трут примерно за 5 минут.'),
    ('Manacles', 'Железные кандалы удерживают существо Маленького или Среднего размера. Освободиться можно проверкой Ловкости Сл 20, сломать их — проверкой Силы Сл 20; у кандалов КД 19 и 15 хитов.'),
    ('Mess Kit', 'Жестяная коробка раскрывается в чашу и плоскую тарелку; внутри помещаются простые столовые приборы. Набор удобен для приготовления и еды на привале.'),
    ('Mirror, steel', 'Небольшое полированное стальное зеркало не разбивается так легко, как стеклянное. Его используют для ухода за собой, подачи отражённого сигнала или осторожного осмотра за углом.'),
    ('Oil (flask)', 'Флягу масла можно метнуть как импровизированное оружие на расстояние до 20 футов. При попадании цель покрывается маслом на 1 минуту и получает дополнительно 5 урона огнём от первого источника огненного урона. Маслом также можно покрыть площадку 5 × 5 футов и поджечь её на 2 раунда; вошедшее туда существо получает 5 урона огнём.'),
    ('Orb', 'Гладкая сфера из стекла, камня или кристалла, настроенная на проведение тайной магии. Волшебник, колдун или чародей может использовать её как магическую фокусировку.'),
    ('Paper (one sheet)', 'Лист качественной бумаги подходит для писем, записей, рисунков и карт. Без футляра он легко мнётся и портится от воды.'),
    ('Parchment (one sheet)', 'Прочный лист выделанной кожи для письма, карт или документов. Пергамент тяжелее бумаги, но лучше переносит долгий путь и сырость.'),
    ('Perfume (vial)', 'Небольшой флакон ароматной смеси. Духи перебивают обычные запахи и помогают завершить образ, но не скрывают след от существ с особенно острым нюхом без решения Мастера.'),
    ('Pick, miner''s', 'Тяжёлая кирка для разбивания камня, работы в шахте и расчистки завалов. Как оружие она считается импровизированной.'),
    ('Piton', 'Короткий железный штырь забивают в камень или дерево, чтобы закрепить верёвку, растяжку либо часть лагерного снаряжения.'),
    ('Poison, basic (vial)', 'Действием яд можно нанести на одно рубящее или колющее оружие либо на три боеприпаса. Покрытие действует 1 минуту; поражённая цель должна пройти спасбросок Телосложения Сл 10, иначе получает 1d4 урона ядом.'),
    ('Pole (10-foot)', 'Прочный десятифутовый шест позволяет проверять глубину, нажимать подозрительные плиты и доставать до объектов, не подходя вплотную.'),
    ('Pot, iron', 'Тяжёлый железный котелок с ручкой выдерживает открытый огонь и вмещает до одного галлона жидкости.'),
    ('Priest''s Pack', 'Набор странствующего служителя с облачением, принадлежностями для обряда, свечами и скромными припасами. Полный состав показан ниже.'),
    ('Pouch', 'Небольшой поясной кошель вмещает примерно 6 фунтов или одну пятую кубического фута содержимого. В нём удобно носить монеты и мелкие предметы.'),
    ('Quiver', 'Жёсткий колчан защищает оперение и позволяет быстро доставать стрелы. В него помещается до двадцати стрел.'),
    ('Ram, portable', 'Переносной таран предназначен для выбивания дверей и разрушения баррикад. Второй персонаж может помочь держать таран: проверка Силы совершается с преимуществом и получает бонус +4.'),
    ('Rations (1 day)', 'Дневной запас сухой походной еды: вяленое мясо, сухари, орехи и другие продукты, которые долго не портятся и не требуют готовки.'),
    ('Reliquary', 'Священный символ в виде небольшого ковчежца для реликвии. Жрец или паладин может использовать его как фокусировку для заклинаний, если держит в руке.'),
    ('Robes', 'Свободное длинное облачение, подходящее учёному, служителю культа или магу. Крой оставляет достаточно места для другой лёгкой одежды.'),
    ('Rod', 'Короткий жезл из дерева, металла или кости, настроенный на проведение тайной магии. Волшебник, колдун или чародей может использовать его как магическую фокусировку.'),
    ('Rope, hempen', 'Недорогая и прочная пеньковая верёвка. У неё 2 хита; разорвать натянутую верёвку можно успешной проверкой Силы Сл 17. Стоимость и вес в справочнике указаны за фут.'),
    ('Rope, silk', 'Тонкая шёлковая верёвка легче пеньковой при той же длине. У неё 2 хита; разорвать натянутую верёвку можно успешной проверкой Силы Сл 17. Стоимость и вес указаны за фут.'),
    ('Sack', 'Грубый тканевый мешок вмещает примерно 30 фунтов или 1 кубический фут содержимого. Пустым он почти не занимает места.'),
    ('Scale, merchant''s', 'Небольшие весы с чашами и набором гирь позволяют точно взвешивать монеты, драгоценные металлы и небольшие товары весом до 2 фунтов.'),
    ('Scholar''s Pack', 'Набор для полевой работы учёного: книга, письменные принадлежности, пергамент и мелкие инструменты. Полный состав показан ниже.'),
    ('Sealing wax', 'Брусок воска плавят над огнём и используют для запечатывания писем или контейнеров. Печатка оставляет на мягком воске узнаваемый знак.'),
    ('Shovel', 'Прочная лопата для земляных работ, расчистки снега и устройства лагеря. Как оружие она считается импровизированной.'),
    ('Signet ring', 'Печатка несёт личный, семейный или должностной знак. Ею оставляют оттиск на сургуче и подтверждают подлинность писем.'),
    ('Signal whistle', 'Пронзительный свист слышен дальше обычного голоса и служит простым сигналом тревоги, сбора или смены караула.'),
    ('Sling bullet', 'Округлый каменный или металлический снаряд для пращи. После боя можно потратить минуту и вернуть половину выпущенных снарядов, если их возможно отыскать.'),
    ('Soap', 'Небольшой кусок мыла для стирки, мытья и удаления обычной грязи или запаха со снаряжения.'),
    ('Spellbook', 'Прочная книга в кожаном переплёте со ста чистыми пергаментными страницами. Волшебник записывает в неё формулы заклинаний; перенос нового заклинания требует времени и специальных чернил.'),
    ('Spike, iron', 'Крупный железный шип для закрепления верёвок, подпирания дверей и временного ремонта деревянных конструкций.'),
    ('Spyglass', 'Система линз в раздвижной трубе увеличивает видимые объекты примерно вдвое. Подзорная труба полезна при наблюдении за берегом, дорогой или полем боя.'),
    ('Sprig of mistletoe', 'Веточка омелы, собранная и подготовленная как друидическая фокусировка. Друид может использовать её вместо материальных компонентов без указанной стоимости.'),
    ('Staff', 'Посох, настроенный на проведение тайной магии. Волшебник, колдун или чародей может использовать его как магическую фокусировку; в бою обычный посох также может служить боевым посохом по решению Мастера.'),
    ('String (10 feet)', 'Десять футов тонкой прочной нити подходят для связывания мелких предметов, растяжек, отвесов и простых сигнализаций.'),
    ('Tent, two-person', 'Складной матерчатый тент с шестами и колышками защищает двух существ Среднего размера от ветра и осадков во время отдыха.'),
    ('Tinderbox', 'Небольшая коробка с огнивом, кремнем и трутом. Действием можно зажечь факел или другой предмет с доступным топливом; обычный костёр разжигается примерно за минуту.'),
    ('Torch', 'Факел горит 1 час, создавая яркий свет в радиусе 20 футов и тусклый свет ещё на 20 футов. При попадании рукопашной атакой горящий факел наносит 1 урон огнём.'),
    ('Totem', 'Предмет из меха, перьев, костей и зубов, подготовленный как друидическая фокусировка. Друид может использовать его вместо материальных компонентов без указанной стоимости.'),
    ('Vial', 'Маленький стеклянный или керамический флакон с пробкой. Он вмещает до 4 унций жидкости.'),
    ('Wand', 'Тонкая палочка из дерева, кости или металла, настроенная на проведение тайной магии. Волшебник, колдун или чародей может использовать её как магическую фокусировку.'),
    ('Waterskin', 'Прошитый кожаный бурдюк с пробкой хранит до 4 пинт жидкости. Указанный вес относится к наполненному бурдюку; пустой заметно легче.'),
    ('Whetstone', 'Мелкозернистый камень для правки и заточки металлических лезвий. Обычное обслуживание не даёт постоянного бонуса к оружию, но помогает сохранять его в рабочем состоянии.'),
    ('Wooden staff', 'Деревянный посох, украшенный природными знаками и подготовленный как друидическая фокусировка. Друид может использовать его вместо материальных компонентов без указанной стоимости.'),
    ('Yew wand', 'Палочка из тиса, падуба или другого особого дерева, подготовленная как друидическая фокусировка. Друид может использовать её вместо материальных компонентов без указанной стоимости.'),
    ('Vestments', 'Церемониальное облачение, обозначающее сан, орден или веру служителя. Оно предназначено для обрядов и официальных появлений, а не для защиты.'),
    ('Fishing tackle', 'В набор входят удилище, шёлковая леска, пробковый поплавок, стальные крючки, грузила, приманки и узкая сеть. Этого достаточно для обычной рыбалки в подходящем водоёме.'),
    ('Alms box', 'Небольшой запираемый ящик для монет и пожертвований. Его можно носить с собой или поставить у алтаря.'),
    ('Block of incense', 'Ароматный брусок медленно тлеет и наполняет помещение дымом. Благовония используют в религиозных обрядах, медитации и церемониях.'),
    ('Censer', 'Металлическая курильница на цепочке, в которой безопасно жгут благовония и угли во время обряда.'),
    ('Little knife', 'Небольшой хозяйственный нож для очинки пера, резки нити, еды и других точных работ. В бою он считается импровизированным оружием.'),
    ('Small knife', 'Небольшой хозяйственный нож для очинки пера, резки нити, еды и других точных работ. В бою он считается импровизированным оружием.')
) AS seed(name_en, description);

UPDATE dndshare.item item
SET data = jsonb_set(item.data, '{desc}', to_jsonb('<p>' || seed.description || '</p>'), true)
FROM item_description_seed seed
WHERE item.user_id IS NULL
  AND item.type_id = 2
  AND lower(COALESCE(item.name_en, '')) = lower(seed.name_en)
  AND (
      btrim(COALESCE(item.data ->> 'desc', '')) = ''
      OR item.data ->> 'desc' LIKE '%покупаемое снаряжение из Книги игрока (2014)%'
  );

-- Legacy background/package helper rows have no stable English name. They are
-- still visible in the handbook and therefore receive useful descriptions too.
WITH helper(id, description) AS (VALUES
    (71::bigint, 'Потрёпанный, но исправный заплечный мешок из старого снаряжения персонажа. Он подходит для переноски обычных дорожных припасов.'),
    (72, 'Короткий железный лом из старого снаряжения персонажа. При подходящей точке опоры он даёт преимущество на проверки Силы, где можно применить рычаг.'),
    (73, 'Рабочий молоток из старого снаряжения персонажа, пригодный для забивания гвоздей, шлямбуров и мелкого ремонта.'),
    (74, 'Небольшой металлический шарик — деталь, грузик или памятная безделушка; конкретное происхождение определяет игрок.'),
    (1423, 'Магический кожаный доспех даёт бонус +1 к КД сверх обычного КД кожаного доспеха.'),
    (1425, 'Отрезок прочной лески, пригодный для рыбалки, тонкой растяжки или связывания небольших предметов.'),
    (1426, 'Короткий железный штырь, который забивают в камень или дерево для крепления верёвки и страховки.'),
    (1427, 'Старая трутница с кремнем, огнивом и сухим трутом. Ею можно зажечь факел действием или развести обычный костёр примерно за минуту.'),
    (1429, 'Неприметный комплект тёмной одежды с капюшоном помогает не выделяться ночью, но сам по себе не даёт бонуса к проверкам Скрытности.'),
    (1431, 'Церемониальная одежда с символами культа. Она показывает принадлежность владельца и может привлечь нежелательное внимание.'),
    (1432, 'Доля монет или ценностей, полученная при разделе добычи. Точное содержимое определяется происхождением персонажа и договорённостью с Мастером.'),
    (1433, 'Амулет с символом культа. Он служит знаком принадлежности, но не является священной фокусировкой без отдельного правила.'),
    (403, 'Мешочек мелкого сухого песка используют для просушки свежих чернил, проверки движения воздуха или как малозаметный груз.'),
    (431, 'Небольшой хозяйственный нож для очинки пера, резки нити и других точных работ. В бою он считается импровизированным оружием.'),
    (351, 'Небольшой запираемый ящик для монет и пожертвований. Его можно носить с собой или поставить у алтаря.'),
    (362, 'Ароматный брусок медленно тлеет и наполняет помещение дымом. Благовония используют в религиозных обрядах и церемониях.'),
    (370, 'Металлическая курильница на цепочке, в которой безопасно жгут благовония и угли во время обряда.'),
    (436, 'Десять футов тонкой прочной нити подходят для связывания мелких предметов, растяжек и простых сигнализаций.'),
    (440, 'Церемониальное облачение обозначает сан, орден или веру служителя и предназначено для обрядов, а не для защиты.')
)
UPDATE dndshare.item item
SET data = jsonb_set(item.data, '{desc}', to_jsonb('<p>' || helper.description || '</p>'), true)
FROM helper
WHERE item.id = helper.id
  AND item.user_id IS NULL
  AND item.type_id = 2
  AND btrim(COALESCE(item.data ->> 'desc', '')) = '';

-- This imported entry stored a Markdown table inside a plain string. Keep the
-- outcome table semantic so the shared rich renderer can present it accessibly.
UPDATE dndshare.item
SET data = jsonb_set(data, '{desc}', to_jsonb(
    '<p>Эта расписная латунная бутылка весит 1 фунт. Если действием вынуть пробку, из неё вырывается густой дым; в конце хода дым вспыхивает безвредным пламенем, и в свободном пространстве в пределах 30 футов появляется ифрит.</p>' ||
    '<p>Когда бутылку открывают впервые, Мастер бросает d100 и определяет её свойство по таблице. После утраты магии бутылка становится обычным сосудом.</p>' ||
    '<table><thead><tr><th>d100</th><th>Результат</th></tr></thead><tbody>' ||
    '<tr><td>01–10</td><td>Ифрит нападает на открывшего бутылку. Через 5 раундов он исчезает, а бутылка теряет магию.</td></tr>' ||
    '<tr><td>11–90</td><td>Ифрит служит открывшему бутылку 1 час, исполняя его приказы, затем возвращается внутрь. Бутылку нельзя снова открыть 24 часа. При втором и третьем открытии происходит то же; при четвёртом ифрит освобождается, исчезает, а бутылка теряет магию.</td></tr>' ||
    '<tr><td>91–100</td><td>Ифрит может трижды сотворить для открывшего бутылку заклинание «Желание». После третьего желания или через 1 час он исчезает, а бутылка теряет магию.</td></tr>' ||
    '</tbody></table>'
), true)
WHERE user_id IS NULL AND type_id = 2 AND lower(COALESCE(name_en, '')) = 'efreeti bottle';

UPDATE dndshare.item_type
SET count_items = (SELECT COUNT(*) FROM dndshare.item WHERE type_id = 2 AND user_id IS NULL)
WHERE id = 2;
